layout(color) uniform half4 amzp_oldcolor;
layout(color) uniform half4 amzp_newcolor;
uniform float amzp_threshold;
uniform float amzp_feather;
uniform float amzp_alpha;
uniform float amzp_lockLuminance;


        void amzRender() {

             float3x3 rgb2yuv = float3x3(
                 0.299,     0.587,    0.114,
                -0.14713,  -0.28886,  0.436,
                 0.615,    -0.51499, -0.10001
            );

             float3x3 yuv2rgb = float3x3(
                1.0,  0.0,      1.13983,
                1.0, -0.39465, -0.58060,
                1.0,  2.03211,  0.0
            );

            float4 texColor = amzTexture(0,amzScreenNorm());
            float3 srcColor = texColor.rgb / texColor.a;
            float3 oldColorYUV = amzp_oldcolor.rgb * rgb2yuv;
            float3 srcColorYUV = srcColor * rgb2yuv;
            float3 diffYUV = abs(oldColorYUV - srcColorYUV);
            diffYUV.yz *= 4.0;
            diffYUV.x *= 0.5;
            float diff = length(diffYUV);
            float b = max(amzp_threshold-max(amzp_feather,0.0005),0.);
            float a = min(amzp_threshold+max(amzp_feather,0.0005),4.);
            float p = smoothstep( a, min(b,a-0.0005), diff);
            float3 newColorAdjRGB = amzp_newcolor.rgb/amzp_newcolor.a;
            if((amzp_lockLuminance>0.5)) {
                float3 newColorAdjYUV = newColorAdjRGB * rgb2yuv;
                newColorAdjYUV.x = srcColorYUV.x;
                newColorAdjRGB = newColorAdjYUV * yuv2rgb;
            } else {
                newColorAdjRGB = srcColor-(amzp_oldcolor.rgb/amzp_oldcolor.a)+newColorAdjRGB;
            }
            amzOutput = mix(texColor,float4(mix(srcColor,newColorAdjRGB,p),1.0)*texColor.a,amzp_newcolor.a*amzp_alpha);

        }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

